namespace ghidra.app.plugin.core.progmgr;







using docking;
using docking.action;
using docking.menu;
using docking.tool;
using generic.theme;
using ghidra.app.context;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.framework.data;
